"""Luo docs/coverage-map.md rekisteristä. Aja: python scripts/gen_coverage_map.py [--check]"""
import pathlib
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
from punakyna.registry import REGISTRY  # noqa: E402

OUT = pathlib.Path(__file__).resolve().parents[1] / 'docs' / 'coverage-map.md'


def render():
    rows = ['# Rule coverage map', '',
            'Generated by `scripts/gen_coverage_map.py` from `punakyna/registry.py`. '
            'Do not edit by hand.', '',
            '| id | category | layer | severity | default | source status | sources | tests |',
            '|---|---|---|---|---|---|---|---|']
    for r in REGISTRY:
        src = '<br>'.join(r.sources)
        rows.append(f'| {r.id} | {r.category} | {r.layer} | {r.severity} | '
                    f'{"on" if r.default_on else "off"} | {r.source_status} | '
                    f'{src} | {", ".join(r.tests)} |')
    n = {s: sum(1 for r in REGISTRY if r.source_status == s)
         for s in ('verified', 'chapter', 'engine')}
    rows += ['', f'Rules: {len(REGISTRY)} (verified source {n["verified"]}, '
             f'chapter-level {n["chapter"]}, engine {n["engine"]}).', '']
    return '\n'.join(rows)


if __name__ == '__main__':
    text = render()
    if '--check' in sys.argv:
        sys.exit(0 if OUT.exists() and OUT.read_text() == text else 1)
    OUT.write_text(text)
